class Solution {
 public:
  void printLinkedListInReverse(ImmutableListNode* head) {
    stack<ImmutableListNode*> stack;

    while (head != nullptr) {
      stack.push(head);
      head = head->getNext();
    }

    while (!stack.empty())
      stack.top()->printValue(), stack.pop();
  }
