class Solution {
 public:
  int countLargestGroup(int n) {
    vector<int> count(9 * 4 + 1);
    for (int i = 1; i <= n; ++i)
      ++count[getDigitSum(i)];
    return ranges::count(count, ranges::max(count));
  }

